1	package com.dawninfotek.logx.extension.log4j12;
2	
3	import java.util.ArrayList;
4	import java.util.HashMap;
5	import java.util.Iterator;
6	import java.util.List;
7	import java.util.Map;
8	
9	import org.apache.log4j.pattern.FormattingInfo;
10	import org.apache.log4j.pattern.LoggingEventPatternConverter;
11	import org.apache.log4j.pattern.PatternParser;
12	import org.apache.log4j.spi.LoggingEvent;
13	
14	public final class LogXBridgePatternConverter extends org.apache.log4j.helpers.PatternConverter {
15		/**
16		 * Pattern converters.
17		 */
18		private LoggingEventPatternConverter[] patternConverters;
19	
20		/**
21		 * Field widths and alignment corresponding to pattern converters.
22		 */
23		private FormattingInfo[] patternFields;
24	
25		/**
26		 * Does pattern process exceptions.
27		 */
28		private boolean handlesExceptions;
29	
30		/**
31		 * Create a new instance.
32		 * 
33		 * @param pattern
34		 *            pattern, may not be null.
35		 */
36		public LogXBridgePatternConverter(final String pattern) {
37			next = null;
38			handlesExceptions = false;
39	
40			List converters = new ArrayList();
41			List fields = new ArrayList();
42			//Original inlementation
43			//Map converterRegistry = null;
44			
45			//For changing the Converter implementation of 'throwable'
46			Map converterRegistry = new HashMap();
47			converterRegistry.put("throwable", LogXThrowableInformationPatternConverter.class);
48			converterRegistry.put("m", LogXMessagePatternConverter.class);
49			converterRegistry.put("message", LogXMessagePatternConverter.class);
50	
51			PatternParser.parse(pattern, converters, fields, converterRegistry, PatternParser.getPatternLayoutRules());
52	
53			patternConverters = new LoggingEventPatternConverter[converters.size()];
54			patternFields = new FormattingInfo[converters.size()];
55	
56			int i = 0;
57			Iterator converterIter = converters.iterator();
58			Iterator fieldIter = fields.iterator();
59	
60			while (converterIter.hasNext()) {
61				Object converter = converterIter.next();
62	
63				if (converter instanceof LoggingEventPatternConverter) {
64					patternConverters[i] = (LoggingEventPatternConverter) converter;
65					handlesExceptions |= patternConverters[i].handlesThrowable();
66				} else {
67					patternConverters[i] = new org.apache.log4j.pattern.LiteralPatternConverter("");
68				}
69	
70				if (fieldIter.hasNext()) {
71					patternFields[i] = (FormattingInfo) fieldIter.next();
72				} else {
73					patternFields[i] = FormattingInfo.getDefault();
74				}
75	
76				i++;
77			}
78		}
79	
80		/**
81		 * {@inheritDoc}
82		 */
83		protected String convert(final LoggingEvent event) {
84			//
85			// code should be unreachable.
86			//
87			StringBuffer sbuf = new StringBuffer();
88			format(sbuf, event);
89	
90			return sbuf.toString();
91		}
92	
93		/**
94		 * Format event to string buffer.
95		 * 
96		 * @param sbuf
97		 *            string buffer to receive formatted event, may not be null.
98		 * @param e
99		 *            event to format, may not be null.
100		 */
101		public void format(final StringBuffer sbuf, final LoggingEvent e) {
102			for (int i = 0; i < patternConverters.length; i++) {
103				int startField = sbuf.length();
104				patternConverters[i].format(e, sbuf);
105				patternFields[i].format(startField, sbuf);
106			}
107		}
108	
109		/**
110		 * Will return false if any of the conversion specifiers in the pattern handles
111		 * {@link Exception Exceptions}.
112		 * 
113		 * @return true if the pattern formats any information from exceptions.
114		 */
115		public boolean ignoresThrowable() {
116			return !handlesExceptions;
117		}
118	
119	}
