import org.apache.logging.log4j.core.LogEvent;
import org.apache.logging.log4j.core.config.plugins.Plugin;
import org.apache.logging.log4j.core.pattern.PatternConverter;
import org.apache.logging.log4j.core.pattern.ConverterKeys;

@Plugin(name = "LogXMessagePatternConverter", category = "Converter")
@ConverterKeys({"m", "message"})
public final class LogXMessagePatternConverter extends PatternConverter {

	private LogXMessagePatternConverter(final String[] options) {
		super("Message", "message");
	}

	public static LogXMessagePatternConverter newInstance(final String[] options) {
		return new LogXMessagePatternConverter(options);
	}

	@Override
	public void format(final LogEvent event, final StringBuilder toAppendTo) {
		String msg = event.getMessage().getFormattedMessage();

		msg = msg.replaceAll("\\t", "").replaceAll("\\r\n", "").replaceAll("\\n", "    ");

		toAppendTo.append(msg);
	}
}

