package com.dawninfotek.logx.extension.log4j12;

import org.apache.logging.log4j.core.LogEvent;
import org.apache.logging.log4j.core.config.plugins.Plugin;
import org.apache.logging.log4j.core.pattern.PatternConverter;
import org.apache.logging.log4j.core.pattern.ConverterKeys;

@Plugin(name = "LogXThrowableInformationPatternConverter", category = "Converter")
@ConverterKeys({"throwable"})
public class LogXThrowableInformationPatternConverter extends PatternConverter {

	private int maxLines = Integer.MAX_VALUE;

	private LogXThrowableInformationPatternConverter(final String name, final String style, final String[] options) {
		super(name, style);

		if ((options != null) && (options.length > 0)) {
			if ("none".equals(options[0])) {
				maxLines = 0;
			} else if ("short".equals(options[0])) {
				maxLines = 1;
			} else {
				try {
					maxLines = Integer.parseInt(options[0]);
				} catch (NumberFormatException ex) {
				}
			}
		}
	}

	public static LogXThrowableInformationPatternConverter newInstance(final String[] options) {
		return new LogXThrowableInformationPatternConverter("Throwable", "throwable", options);
	}

	@Override
	public void format(final LogEvent event, final StringBuilder toAppendTo) {
		if (maxLines != 0) {
			Throwable t = event.getThrown();

			if (t != null) {
				String[] stringRep = LogXThrowableRenderer.doRender(t);

				int length = stringRep.length;
				if (maxLines < 0) {
					length += maxLines;
				} else if (length > maxLines) {
					length = maxLines;
				}

				for (int i = 0; i < length; i++) {
					String string = stringRep[i];
					toAppendTo.append(string);
					if (i < length - 1) {
						toAppendTo.append("\n");
					}
				}
			}
		}
	}

	@Override
	public boolean handlesThrowable() {
		return true;
	}
}

